def flask(s): return 'from flask import Flask, request, jsonify, redirect, url_for, make_response, abort\napp = Flask(__name__)\n'+s+'\nif __name__ == "__main__":\n    app.run(host="127.0.0.1", port=8000)\n'
def django(s, routes): return 'from django.http import HttpResponse, JsonResponse, HttpResponseNotAllowed\nfrom django.shortcuts import redirect\nfrom django.urls import path, reverse\nimport json\n'+s+'\nurlpatterns = [\n'+routes+'\n]\n'
def fastapi(s): return 'from fastapi import FastAPI, Query, HTTPException, Response, status\nfrom fastapi.responses import PlainTextResponse, RedirectResponse\nfrom pydantic import BaseModel, Field\napp = FastAPI()\n'+s+'\n'
course('flask','Flask','python','Examples use Flask 3 and Python 3.10 or later.','In a practice folder create a virtual environment and install Flask with python -m pip install flask. Save one example as app.py and run python app.py. Use http://127.0.0.1:8000.','Flask is a small Python web framework. It connects URL routes to Python functions.',[
L('first-route','Reply with text','A route decorator connects GET / to a function. Its return value becomes the reply.',flask('@app.get("/")\ndef hello():\n    return "Hello, Asha!"'),'Hello, Asha!','Change the message.','Keep the decorator directly above the function it belongs to.'),
L('json','Reply with JSON','jsonify turns data into a JSON response. Open GET /book.',flask('@app.get("/book")\ndef book():\n    return jsonify(title="Moon Trip", pages=24)'),'{"pages":24,"title":"Moon Trip"}','Add an author field.','JSON field order is not meaningful; Flask may sort keys.'),
L('path-values','Read a name from a path','Angle brackets mark a path input. GET /hello/Ravi passes Ravi to the function.',flask('@app.get("/hello/<name>")\ndef hello(name):\n    return f"Hi, {name}!"'),'Hi, Ravi!','Visit /hello/Asha.','A path value is untrusted input; do not paste it into raw HTML.'),
L('integer-routes','Check a path number','The int converter accepts a whole-number path value. Open GET /double/4.',flask('@app.get("/double/<int:n>")\ndef twice(n):\n    return jsonify(answer=n * 2)'),'{"answer":8}','Try /double/cat and observe 404.','A route converter decides whether the route matches before the function runs.'),
L('query','Read a query value','request.args reads query-string values. Open GET /search?q=cat.',flask('@app.get("/search")\ndef search():\n    return jsonify(term=request.args.get("q", ""))'),'{"term":"cat"}','Visit /search with no query.','Query values are text unless you convert them.'),
L('post-json','Read a JSON request','Send POST /books with application/json and {"title":"Moon Trip"}. The code checks that the body is an object with text title.',flask('@app.post("/books")\ndef create():\n    data = request.get_json(silent=True)\n    if not isinstance(data, dict) or not isinstance(data.get("title"), str):\n        return jsonify(error="Title needed"), 400\n    return jsonify(title=data["title"]), 201'),'{"title":"Moon Trip"}','Send an empty object.','Check parsed data before indexing into it.'),
L('status','Report a missing item','Returning a response with 404 tells the client that this book was not found. Open GET /missing.',flask('@app.get("/missing")\ndef missing():\n    return jsonify(error="Book not found"), 404'),'{"error":"Book not found"}','Inspect the status with curl -i.','A failure should not pretend to be a successful 200 response.'),
L('redirects','Follow a named route','url_for builds a URL from a function endpoint name. GET /start redirects a browser to /hello.',flask('@app.get("/start")\ndef start():\n    return redirect(url_for("hello"))\n@app.get("/hello")\ndef hello():\n    return "Welcome"'),'Welcome','Inspect the first response Location header.','The endpoint name here is the Python function name, not the URL text.'),
L('headers','Add a response header','make_response lets you add metadata before sending a reply. GET /note has Cache-Control: no-store.',flask('@app.get("/note")\ndef note():\n    response = make_response("Practice note")\n    response.headers["Cache-Control"] = "no-store"\n    return response'),'Practice note','Inspect the header with curl -i.','Headers describe the response; changing one does not change its body.'),
L('before-request','Run a shared check','before_request runs before route handlers. This practice check rejects paths under /closed. Visit GET /closed/books.',flask('@app.before_request\ndef check_path():\n    if request.path.startswith("/closed/"):\n        return "Closed for practice", 403\n@app.get("/closed/books")\ndef books():\n    return "Books"'),'Closed for practice','Visit a route outside that prefix.','Returning a response stops the request from reaching its view.'),
L('error-handlers','Give a friendly error page','An error handler formats a known error. GET /missing uses abort to raise a 404.',flask('@app.errorhandler(404)\ndef not_found(error):\n    return "Page not found", 404\n@app.get("/missing")\ndef missing():\n    abort(404)'),'Page not found','Try a different unknown URL.','Keep the error status when returning a friendly error body.'),
L('test-client','Test a request in Python','The test client calls the app without an open port. This example prints the returned JSON score.','from flask import Flask, jsonify\napp = Flask(__name__)\n@app.get("/score")\ndef score():\n    return jsonify(score=8)\nwith app.test_client() as client:\n    response = client.get("/score")\n    print(response.get_json()["score"])','8','Change the score and compare the test result.','Use the test client only for tests; it is not a public server.')])
course('django','Django','python','Examples use Django 5.2 LTS and Python 3.10 or later.','Install django~=5.2, run django-admin startproject school, then enter school. Replace school/urls.py with each example and run python manage.py runserver 127.0.0.1:8000. These view examples need no database tables.','Django is a Python web framework with routing, views, forms and data tools. These first lessons focus on simple views.',[
L('first-view','Make a text view','A view is a function that returns a response. path connects the empty path to hello. Open GET /.',django('def hello(request):\n    return HttpResponse("Hello, Asha!")','path("", hello),'),'Hello, Asha!','Change the greeting.','Django path patterns do not start with a slash.'),
L('json','Send named data','JsonResponse turns a Python dictionary into JSON. Open GET /book/.',django('def book(request):\n    return JsonResponse({"title": "Moon Trip", "pages": 24})','path("book/", book),'),'{"title": "Moon Trip", "pages": 24}','Add an author field.','Use a dictionary by default; lists need safe=False.'),
L('integer-paths','Read a checked path number','The int converter turns a matching path part into a Python int. Open GET /double/4/.',django('def twice(request, n):\n    return JsonResponse({"answer": n * 2})','path("double/<int:n>/", twice),'),'{"answer": 8}','Try /double/cat/.','A nonmatching converter produces 404 before the view runs.'),
L('text-paths','Read a name from the path','The str converter passes one path segment as text. Open GET /hello/Ravi/.',django('def hello(request, name):\n    return HttpResponse("Hi, " + name + "!", content_type="text/plain")','path("hello/<str:name>/", hello),'),'Hi, Ravi!','Visit /hello/Asha/.','Use text/plain or proper escaping when returning user text.'),
L('query','Read a query string','request.GET contains query values. Visit GET /search/?q=cat.',django('def search(request):\n    return JsonResponse({"term": request.GET.get("q", "")})','path("search/", search),'),'{"term": "cat"}','Leave out q and compare.','Despite its name, request.GET describes query data, not the entire request.'),
L('methods','Allow only a chosen method','A view can inspect request.method. A GET request to /check/ is accepted; another method gets 405.',django('def check(request):\n    if request.method != "GET":\n        return HttpResponseNotAllowed(["GET"])\n    return HttpResponse("Ready")','path("check/", check),'),'Ready','Send a HEAD request and inspect the allowed-method header.','Use 405 for an unsupported method, not 404.'),
L('named-routes','Build a URL from its name','reverse finds a route by name and fills its inputs. Open GET /link/.',django('def hello(request, name):\n    return HttpResponse(name)\ndef link(request):\n    return HttpResponse(reverse("hello", kwargs={"name": "Asha"}))','path("hello/<str:name>/", hello, name="hello"),\npath("link/", link),'),'/hello/Asha/','Change the name passed to reverse.','The keyword name must match the path input name.'),
L('redirects','Send a client elsewhere','redirect creates an HTTP redirect. GET /start/ sends a browser to /hello/.',django('def start(request):\n    return redirect("hello")\ndef hello(request):\n    return HttpResponse("Welcome")','path("start/", start),\npath("hello/", hello, name="hello"),'),'Welcome','Inspect the first response status and Location.','A redirect causes a second request from the client.'),
L('missing-items','Return an error status','The response status describes the result. Open GET /missing/ to see a 404 reply.',django('def missing(request):\n    return JsonResponse({"error": "Book not found"}, status=404)','path("missing/", missing),'),'{"error": "Book not found"}','Inspect the 404 status too.','Returning error text with status 200 can mislead clients.'),
L('list-data','Return a list safely','JsonResponse normally expects a dictionary. A dictionary can hold a list under a clear key. Open GET /books/.',django('def books(request):\n    return JsonResponse({"books": ["Moon Trip", "Sun Trip"]})','path("books/", books),'),'{"books": ["Moon Trip", "Sun Trip"]}','Add a third title.','A named wrapper leaves room for more response information later.'),
L('headers','Set response metadata','A response object can store headers. GET /note/ has a no-store cache rule.',django('def note(request):\n    response = HttpResponse("Practice note", content_type="text/plain")\n    response["Cache-Control"] = "no-store"\n    return response','path("note/", note),'),'Practice note','Inspect Cache-Control with curl -i.','Set headers before returning the response.'),
L('health-view','Make a small health response','A health route gives a small answer that a checker can read. GET /health/ returns one Boolean field.',django('def health(request):\n    return JsonResponse({"ready": True})','path("health/", health),'),'{"ready": true}','Change the route name and request that URL.','A simple health response does not prove every outside service is working.')])
course('fastapi','FastAPI','python','Examples use FastAPI with Pydantic 2 and Python 3.10 or later.','Install fastapi and uvicorn with python -m pip install fastapi uvicorn. Save one example as app.py and run uvicorn app:app --host 127.0.0.1 --port 8000. Use the stated route on that address.','FastAPI is a Python framework for web APIs. Type hints help it check inputs and describe routes.',[
L('first-route','Return a greeting','A route decorator maps GET / to a function. PlainTextResponse makes a plain text reply.',fastapi('@app.get("/", response_class=PlainTextResponse)\ndef hello():\n    return "Hello, Asha!"'),'Hello, Asha!','Change the greeting.','Without a text response class, a returned string is sent as JSON text.'),
L('json','Return a data object','A Python dictionary becomes JSON. Open GET /book.',fastapi('@app.get("/book")\ndef book():\n    return {"title": "Moon Trip", "pages": 24}'),'{"title":"Moon Trip","pages":24}','Add an author field.','Return Python data instead of manually joining JSON strings.'),
L('path-types','Check a path number','The n: int type lets FastAPI parse and check a route input. Open GET /double/4.',fastapi('@app.get("/double/{n}")\ndef twice(n: int):\n    return {"answer": n * 2}'),'{"answer":8}','Try /double/cat and inspect 422.','Invalid input is rejected before the function body runs.'),
L('query-defaults','Supply a query default','An input not in the path is read from the query. GET /page with no n uses its default.',fastapi('@app.get("/page")\ndef page(n: int = 1):\n    return {"page": n}'),'{"page":1}','Visit /page?n=3.','A default makes the query input optional.'),
L('query-limits','Limit an input range','Query can add rules such as a minimum and maximum. Open GET /page?n=3.',fastapi('@app.get("/page")\ndef page(n: int = Query(default=1, ge=1, le=10)):\n    return {"page": n}'),'{"page":3}','Try n=0 and n=11.','Type checks alone do not enforce a useful range.'),
L('request-models','Check a JSON body','A Pydantic model describes body fields. Send POST /books with application/json and {"title":"Moon Trip","pages":24}.',fastapi('class Book(BaseModel):\n    title: str\n    pages: int = Field(gt=0)\n@app.post("/books", status_code=201)\ndef create(book: Book):\n    return book'),'{"title":"Moon Trip","pages":24}','Try pages equal to zero.','Positive page counts need a rule such as gt=0.'),
L('response-models','Choose returned fields','A response model describes the public data. GET /book leaves out the internal note.',fastapi('class PublicBook(BaseModel):\n    title: str\n@app.get("/book", response_model=PublicBook)\ndef book():\n    return {"title": "Moon Trip", "internal_note": "draft"}'),'{"title":"Moon Trip"}','Add pages to the model and returned data.','Only return data the client should receive, even when filtering is available.'),
L('errors','Report a missing item','HTTPException stops normal handling with an error reply. Open GET /missing.',fastapi('@app.get("/missing")\ndef missing():\n    raise HTTPException(status_code=404, detail="Book not found")'),'{"detail":"Book not found"}','Inspect the status as well as the body.','Raise HTTPException; returning it is not the same action.'),
L('headers','Add response metadata','The Response input lets a function set headers. Open GET /note.',fastapi('@app.get("/note")\ndef note(response: Response):\n    response.headers["Cache-Control"] = "no-store"\n    return {"note": "Practice"}'),'{"note":"Practice"}','Inspect Cache-Control with curl -i.','A header changes metadata, not the JSON field values.'),
L('redirects','Point to another URL','RedirectResponse sends a Location header. A browser following GET /start reaches /hello.',fastapi('@app.get("/start")\ndef start():\n    return RedirectResponse("/hello", status_code=302)\n@app.get("/hello", response_class=PlainTextResponse)\ndef hello():\n    return "Welcome"'),'Welcome','Inspect the first 302 response.','Choose the redirect status deliberately, especially for non-GET methods.'),
L('lists','Return a typed list','A list response can contain several small data objects. Open GET /books.',fastapi('class Book(BaseModel):\n    title: str\n@app.get("/books", response_model=list[Book])\ndef books():\n    return [{"title": "Moon Trip"}, {"title": "Sun Trip"}]'),'[{"title":"Moon Trip"},{"title":"Sun Trip"}]','Add another book.','Every list item must fit the response model.'),
L('async-routes','Wait without blocking','An async route can await an async operation. GET /score waits for a completed coroutine and returns its result.',fastapi('async def read_score():\n    return 8\n@app.get("/score")\nasync def score():\n    value = await read_score()\n    return {"score": value}'),'{"score":8}','Return 6 from read_score.','Do not put blocking work in async routes and assume async makes it faster.')])
